-- ============================================================
-- 伝統工芸（テーマID: 14, category_id: 6）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(6, 14, '西陣織の主な産地として正しいのはどれか。', '東山区', '上京区西陣地区', '伏見区', '右京区太秦', 1, '西陣織は京都市上京区を中心とした「西陣」地区で生産される絹織物の総称です。応仁の乱後に西軍の陣が置かれた地（西陣）で機業が発展したことが名の由来です。錦・緞子・金らんなど多種多様な織物を含みます。', 1, false),
(6, 14, '京友禅の技法を大成した人物はだれか。', '宮崎友禅斎', '尾形光琳', '本阿弥光悦', '野々村仁清', 0, '京友禅は江戸時代前期の扇絵師・宮崎友禅斎（みやざきゆうぜんさい）が考案・大成した技法が名の由来です。繊細な模様と多彩な色彩が特徴で、米糊を使った糸目友禅が代表的な技法です。', 1, false),
(6, 14, '西陣織の代表的な織物「錦」の特徴として正しいのはどれか。', '単色で模様が少ない', '多色の緯糸（よこいと）で文様を表す多彩な織物', '金糸のみで織られた高級品', '縦糸で模様を表す特殊織物', 1, '錦（にしき）は多色の緯糸（よこいと）を使って複雑な文様を表した多彩な織物です。西陣の代表的な織物で、袋帯・能装束・打掛などに使われます。', 2, false),
(6, 14, '京都を代表する漆工芸「京漆器」で、螺鈿（らでん）とはどのような技法か。', '漆を幾重にも塗り重ねる技法', '貝殻を薄く削り文様を嵌め込む技法', '金粉・銀粉を蒔く技法', '木材を刻んで文様を作る技法', 1, '螺鈿（らでん）は夜光貝・アワビなどの貝殻を薄く削り、漆地に文様として嵌め込む加飾技法です。貝が放つ虹色の光沢が美しく、京漆器の高級装飾技法として知られています。', 2, false),
(6, 14, '京都の伝統的な扇子のうち、神事・能楽などに使われる格式高い扇はどれか。', '舞扇', '桧扇（ひおうぎ）', '夏扇', '絵扇', 1, '桧扇（ひおうぎ）は桧の薄板を重ねた扇で、平安時代から宮廷で使われてきた格式高い扇です。現在も葵祭などの祭礼・神事・雅楽・能楽で使われています。', 2, false),
(6, 14, '京都の西陣織で「御召（おめし）」とは何か。', '将軍専用に製造された生地', '縮緬（ちりめん）の一種で先染めの絹織物', '金糸を多用した礼服用生地', '麻と絹を混紡した生地', 1, '御召（おめし）は先に染めた糸を使い、縮れ（しぼ）のある独特の風合いを持つ絹織物です。徳川11代将軍・家斉が好んで着用したことから「お召し物」→「御召」と呼ばれるようになったとされます。', 3, false),
(6, 14, '京都の伝統工芸「京鹿の子絞り」とはどのような技法か。', '鹿の子の形に染料を付ける技法', '布を糸で細かく括り染色して絞り模様を出す技法', '鹿の皮を使った染色技法', '金属型を使った染色技法', 1, '京鹿の子絞り（きょうかのこしぼり）は布を指先で均一につまみ、糸で細かく括ってから染色することで、鹿の子の斑点に似た独特の模様を作り出す絞り染めの技法です。', 2, false),
(6, 14, '西陣織を含む京都の繊維産業の振興のために設立された研究機関はどれか。', '京都工芸繊維大学', '京都市産業技術研究所', '西陣織会館', '京都繊維工業試験場', 1, '西陣織など京都の伝統産業の技術支援を行う公的機関として、京都市産業技術研究所（旧・京都市工業試験場）があります。染色・織物・漆芸など幅広い伝統工芸の技術研究を担っています。', 3, false),
(6, 14, '京都の伝統工芸として国の「伝統的工芸品」に指定されているものはどれか。', '京うちわ', '西陣織', '京こまや', '七味唐辛子', 1, '西陣織は経済産業省が指定する「伝統的工芸品」に認定されています。京都の伝統的工芸品には西陣織のほか、京友禅・京漆器・京染め・京焼・清水焼なども含まれます。', 2, false),
(6, 14, '「本染め（京染め）」と「プリント（捺染）」の主な違いはどれか。', '使用する布の種類が異なる', '本染めは繊維の奥まで染料が浸透し、プリントは表面に色を印刷する', '本染めは化学染料、プリントは天然染料を使う', '本染めは機械、プリントは手作業で行う', 1, '本染め（手染め）は染料が繊維の内部まで浸透して定着するため、洗っても色落ちしにくく、深みのある色彩が特徴です。プリント（捺染）は染料を表面に印刷する方法で、複雑な多色柄を効率よく表現できます。', 2, false),
(6, 14, '京都の「京くみひも」とはどのような工芸品か。', '竹で作った組み細工', '絹糸などを組んで作る紐（ひも）工芸', '和紙を使った組み細工', '皮革を使った組み細工', 1, '京くみひもは絹糸などを高台（たかだい）・角台などの特殊な台を使い、精巧に組み上げた紐工芸です。帯締め・羽織紐・刀の下緒などに使われ、色の組み合わせや組み方によって多様な文様が生まれます。', 2, false),
(6, 14, '京都の仏師が制作する「京仏像」と「京仏具」について正しいのはどれか。', '仏像と仏具はまったく別の職人が作る', '仏師が仏像・仏具の両方を一括して制作する', '仏像は京都産、仏具は奈良産が正式', '近代以降に始まった産業で歴史は浅い', 0, '京仏像（京仏師）と京仏具はそれぞれ専門の職人が分業して制作します。仏師が仏像を彫刻し、漆師・彩色師・截金師（きりかねし）などが彩色・加飾を担うという高度な分業体制で高品質な作品が生まれます。', 3, false),
(6, 14, '「西陣織」の「西陣」という地名の由来となった出来事はどれか。', '西国から伝わった織物', '平安時代の西の都', '応仁の乱で西軍の陣地となった地', '西洋の技術を導入した地', 2, '西陣の名は、1467〜1477年の応仁の乱において西軍（山名宗全側）の本陣が置かれた上京区付近が由来です。戦乱で離散した機屋がこの地に戻って操業を再開し、西陣織の産地として発展しました。', 1, false),
(6, 14, '京都の伝統工芸「京焼・清水焼」は何節（カテゴリ）に属するか。', '伝統工芸', '芸術・文化', '食文化', '建築・庭園・美術', 1, 'このアプリの分類では、京焼・清水焼は「芸術・文化」カテゴリのテーマ「京焼・清水焼」として扱われています。焼き物は染色・織物とは異なる専門分野として独立しています。', 1, false),
(6, 14, '京都の「京扇子」の生産地として有名な地域はどれか。', '東山五条付近', '西陣地区', '嵐山地区', '伏見地区', 0, '京扇子は主に東山五条付近（清水坂周辺）を中心とした地域で生産されており、観光地としての清水寺周辺にも多くの扇子店が並んでいます。また上京区にも伝統的な扇子の工房が残っています。', 2, false),
(6, 14, '「蒔絵（まきえ）」とはどのような漆工芸の技法か。', '漆地に金銀の粉を蒔いて文様を表す技法', '漆を薄く引いて木目を生かす技法', '漆を多層に塗り重ねて磨く技法', '漆と貝を組み合わせる技法', 0, '蒔絵（まきえ）は漆で絵を描き、乾かないうちに金・銀などの粉を蒔いて文様を表す漆芸技法です。京都は蒔絵の産地としても有名で、高級な弁当箱・硯箱・刀の鞘などに施されています。', 2, false),
(6, 14, '友禅染めの技法で「糸目糊（いとめのり）」の役割はどれか。', '布を固める糊', '色が混ざらないように境界線となる防染糊', '発色を良くする補助材', '生地を柔らかくする加工剤', 1, '糸目糊（いとめのり）は米ぬかや糊を原料にした防染糊で、色と色の境界線に細い糸のように絞り出すことで、各色が混ざらないように区切る役割を果たします。これにより繊細な友禅模様が表現されます。', 3, false),
(6, 14, '西陣織の技法「絽（ろ）」の特徴として正しいのはどれか。', '厚みのある冬用の生地', '経糸を絡め合わせた透け感のある夏用の生地', '金糸・銀糸を多用した礼装用生地', '縞模様を基本とする普段着用生地', 1, '絽（ろ）は経糸（たていと）を絡め合わせることで生まれる透け感のある薄手の織物で、夏物の着物・帯・帯揚げなどに使われます。涼しげな見た目と通気性の良さが特徴の夏を代表する西陣の織物です。', 3, false),
(6, 14, '京都の伝統工芸「京組紐（くみひも）」の生産地として最も集中しているのはどこか。', '西陣地区', '上京区堀川通周辺', '宇治市', '伏見区', 0, '京くみひも（京組紐）は西陣地区を中心に生産されており、西陣の絹糸産業と密接に関連しています。帯締め・帯揚げ・羽織紐など和装小物の重要な部品として今も職人が手作業で制作しています。', 3, false),
(6, 14, '「京焼」のほかに、五条坂・清水坂周辺で生産される焼き物の名称はどれか。', '萩焼', '清水焼', '備前焼', '信楽焼', 1, '清水焼（きよみずやき）は東山区の清水坂・五条坂周辺で生産される陶磁器で、京焼と並ぶ京都を代表する焼き物です。絵付けが豊かで色彩鮮やかな作風が特徴で、観光土産としても広く知られています。', 1, false);

